214	// one, while the "Mr." and "Dr." titles and the decimal inside the fourth
215	// sentence must not.
216	const PASSAGE = [
217	  'Mr. Alder opened the shop at nine. Nobody came in until noon! When the first',
218	  'customer arrived, Dr. Wren asked whether the prices had changed. They had',
219	  'risen by 3.5 percent since spring. "Is that all?" she said. He nodded, and',
220	  'the afternoon went by quietly. By closing time the till held forty dollars.',
221	].join('\n');
222	
223	const CASES = [
224	  ["", 0],
225	  [" ", 0],
226	  [".", 0],
227	  ["a", 1],
228	  ["a.", 1],
229	  ["a. b.", 2],
230	  ["a! b? c.", 3],
231	  ["a!? b", 2],
232	];
