235	  assert.equal(sentenceCount(''), 0);
236	});
237	
238	test('returns 0 for whitespace only', () => {
239	  assert.equal(sentenceCount('  \n\t  '), 0);
240	});
241	
242	test('returns 0 for terminators with no words', () => {
243	  assert.equal(sentenceCount('... ?! . ! ?'), 0);
244	});
