259	  for (const bad of [undefined, null, 7, {}, ['One.']]) {
260	    assert.throws(() => sentenceCount(bad), (err) => {
261	      assert.ok(err instanceof TypeError);
262	      assert.ok(err.message.startsWith('sentenceCount:'));
263	      return true;
264	    });
