382	// "keeper" x3, "lamp" x3, "night" x2, "tower" x2, "storm" x1. Stop words
383	// (the, a, of, and, on, in, was) are present on purpose and must not appear.
384	const PASSAGE = [
385	  'The keeper lit the lamp. The lamp was old, and the keeper was older.',
